/**
 * Serializer for EventQuestion with nested writable options.
 *
 * Supports creating and updating questions with nested options in a single request.
 * Options can be provided as an array of objects with option_text and order.
 *
 * For updates:
 * - Options with 'id' field: update existing
 * - Options without 'id': create new
 * - Existing options not in payload: deleted
 */
export type EventQuestion = {
    readonly id: string;
    event: string;
    readonly event_title: string;
    question_title: string;
    question_body: string;
    /**
     * * `short_answer` - Short Answer
     * * `long_answer` - Long Answer
     * * `upload` - Upload
     * * `multiple_choice` - Multiple Choice
     * * `single_choice` - Single Choice
     * * `slider` - Slider
     */
    question_type?: 'short_answer' | 'long_answer' | 'upload' | 'multiple_choice' | 'single_choice' | 'slider';
    readonly question_type_display: string;
    required?: boolean;
    public?: boolean;
    order?: number;
    max_value?: number | null;
    min_value?: number | null;
    options?: Array<EventQuestionNestedOption>;
    readonly created_at: string;
    readonly updated_at: string;
    /**
     *  links
     */
    readonly _links: {
        /**
         * Link to this question
         */
        self: string;
        /**
         * Link to the event
         */
        event?: string;
    };
};

