/**
 * Serializer for EventAttendance.
 */
export type EventAttendanceWritable = {
    event: number;
    attendee: number;
    check_in_by?: number | null;
    check_out_by?: number | null;
};

export type EventAuthorizationWritable = {
    event: string;
    /**
     * * `PENDING` - Pending Review
     * * `APPROVED` - Approved
     * * `REJECTED` - Rejected
     * * `POSTPONED` - Postponed
     * * `CANCELLED` - Cancelled
     */
    status?: 'PENDING' | 'APPROVED' | 'REJECTED' | 'POSTPONED' | 'CANCELLED';
    reason?: string | null;
    notes?: string | null;
};

export type EventCreateUpdateWritable = {
    display_code: string;
    /**
     * display title
     */
    title: string;
    /**
     * * `DRAFTING` - Drafting
     * * `PUBLISHED` - Published
     * * `OPEN` - Open for Registration
     * * `CLOSED` - Closed
     * * `IN_PROGRESS` - In Progress
     * * `COMPLETED` - Completed
     * * `DELETED` - Deleted
     * * `CANCELLED` - Cancelled
     * * `POSTPONED` - Postponed
     * * `ARCHIVED` - Archived
     */
    status?: 'DRAFTING' | 'PUBLISHED' | 'OPEN' | 'CLOSED' | 'IN_PROGRESS' | 'COMPLETED' | 'DELETED' | 'CANCELLED' | 'POSTPONED' | 'ARCHIVED';
    event_type?: number | null;
    timezone: string;
    short_description?: string | null;
    long_description?: string | null;
    what_to_bring?: string | null;
    important_information?: string | null;
    theme?: string | null;
    anchor_verse?: string | null;
    expected_attendance?: number | null;
    maximum_attendance?: number | null;
    /**
     * URL safe title
     */
    url_safe_title?: string | null;
    start_datetime: string;
    end_datetime: string;
    /**
     * The organisation hosting this event.
     */
    organisation?: number | null;
};

