export type EventListWritable = {
    display_code: string;
    display_identifier?: string;
    /**
     * display title
     */
    title: string;
    /**
     * * `DRAFTING` - Drafting
     * * `PUBLISHED` - Published
     * * `OPEN` - Open for Registration
     * * `CLOSED` - Closed
     * * `IN_PROGRESS` - In Progress
     * * `COMPLETED` - Completed
     * * `DELETED` - Deleted
     * * `CANCELLED` - Cancelled
     * * `POSTPONED` - Postponed
     * * `ARCHIVED` - Archived
     */
    status?: 'DRAFTING' | 'PUBLISHED' | 'OPEN' | 'CLOSED' | 'IN_PROGRESS' | 'COMPLETED' | 'DELETED' | 'CANCELLED' | 'POSTPONED' | 'ARCHIVED';
    event_type?: number | null;
    /**
     * The organisation hosting this event.
     */
    organisation?: number | null;
    short_description?: string | null;
    start_datetime: string;
    end_datetime: string;
    timezone: string;
    created_by?: number | null;
};

export type EventPermissionWritable = {
    name: string;
    code: string;
    description?: string | null;
    /**
     * * `GENERAL` - General Permissions
     * * `REGISTRATION` - Registration Permissions
     * * `PRODUCT_MANAGEMENT` - Product Management Permissions
     * * `CONTENT_MANAGEMENT` - Content Management Permissions
     * * `STAFF_MANAGEMENT` - Staff Management Permissions
     * * `PAYMENT_MANAGEMENT` - Payment Management Permissions
     * * `BOOKING_MANAGEMENT` - Booking Management Permissions
     * * `RESOURCE_MANAGEMENT` - Resource Management Permissions
     * * `REPORTING` - Reporting Permissions
     */
    category?: 'GENERAL' | 'REGISTRATION' | 'PRODUCT_MANAGEMENT' | 'CONTENT_MANAGEMENT' | 'STAFF_MANAGEMENT' | 'PAYMENT_MANAGEMENT' | 'BOOKING_MANAGEMENT' | 'RESOURCE_MANAGEMENT' | 'REPORTING';
};

export type EventPermissionAssignmentWritable = {
    event: string;
    user: number;
    permission: number;
    read_only?: boolean;
    allow_update?: boolean;
    allow_delete?: boolean;
    allow_create?: boolean;
};

/**
 * List/Detail serializer for EventProductCategory with HATEOAS links.
 */
export type EventProductCategoryWritable = {
    event: number;
    /**
     * Product Category
     */
    category: number;
    product: number | null;
};

/**
 * Serializer for EventQuestion with nested writable options.
 *
 * Supports creating and updating questions with nested options in a single request.
 * Options can be provided as an array of objects with option_text and order.
 *
 * For updates:
 * - Options with 'id' field: update existing
 * - Options without 'id': create new
 * - Existing options not in payload: deleted
 */
export type EventQuestionWritable = {
    event: string;
    question_title: string;
    question_body: string;
    /**
     * * `short_answer` - Short Answer
     * * `long_answer` - Long Answer
     * * `upload` - Upload
     * * `multiple_choice` - Multiple Choice
     * * `single_choice` - Single Choice
     * * `slider` - Slider
     */
    question_type?: 'short_answer' | 'long_answer' | 'upload' | 'multiple_choice' | 'single_choice' | 'slider';
    required?: boolean;
    public?: boolean;
    order?: number;
    max_value?: number | null;
    min_value?: number | null;
    options?: Array<EventQuestionNestedOptionWritable>;
};

/**
 * Serializer for EventQuestionAnswer with nested writable selected options.
 *
 * Supports creating and updating answers with option selections.
 * Validates option selections against question constraints.
 */
export type EventQuestionAnswerWritable = {
    question: string;
    attendee: string;
    answer_text: string;
};

export type EventQuestionAnswerChoiceWritable = {
    answer: number;
    option: number;
};

/**
 * Serializer for EventQuestionAnswer with nested writable selected options.
 *
 * Supports creating and updating answers with option selections.
 * Validates option selections against question constraints.
 */
export type EventQuestionAnswerRequestWritable = {
    question: string;
    attendee: string;
    answer_text: string;
    /**
     * List of option IDs to select for choice questions
     */
    selected_option_ids?: Array<number>;
    /**
     * ID of uploaded Resource for upload-type questions
     */
    upload_resource_id?: number;
    /**
     * Direct URL/path to uploaded file (alternative to upload_resource_id)
     */
    upload_url?: string;
};

/**
 * Nested option serializer used for create/update question payloads.
 */
export type EventQuestionNestedOptionWritable = {
    option_text: string;
    order?: number;
};

export type EventQuestionOptionWritable = {
    question?: string;
    option_text: string;
    order?: number;
};

export type EventReviewWritable = {
    event: string;
    rating: number;
    comment?: string | null;
};

export type EventRoleWritable = {
    name: string;
    description?: string | null;
    code: string;
    /**
     * * `ADMINISTRATIVE` - Administrative Roles
     * * `VOLUNTEER` - Volunteer Roles
     * * `SPEAKER` - Speaker Roles
     * * `COORDINATOR` - Coordinator Roles
     * * `SUPPORT_STAFF` - Support Staff Roles
     */
    category?: 'ADMINISTRATIVE' | 'VOLUNTEER' | 'SPEAKER' | 'COORDINATOR' | 'SUPPORT_STAFF';
};

export type EventRoleAssignmentWritable = {
    event: string;
    user: number;
    role: number;
};

